uniform mat4 rot_rand1; uniform mat4 rot_rand2; uniform mat4 rot_rand3; uniform mat4 rot_rand4;

float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }
float lum(vec3 x) { return dot(x, vec3(0.32, 0.49, 0.29)); }
float lum(vec4 x) { return dot(x.rgb, vec3(0.32, 0.49, 0.29)); }
float sat(float x) { return clamp(x, 0.0, 1.0); }
vec2 sat(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 sat(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 sat(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

vec3 GetPixel(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec3 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv).xyz; }
vec3 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv).xyz; }
vec3 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv).xyz; }
vec4 noise3(vec2 uv) { return texture(sampler_noise_lq, uv); }
vec3 GetMain(vec2 uv) { return texture(sampler_main, uv).xyz; }
vec2 multiply(vec2 v, mat2 m) { return m * v; }
vec3 multiply(vec3 v, mat3 m) { return m * v; }
vec4 multiply(vec4 v, mat4 m) { return m * v; }
vec4 textureBias(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_pw_noise_lq sampler_noise_lq
#define GP GetPixel
#define GB GetBlur1
sampler sampler_pw_noise_lq;
static vec2 hor = vec2 ((1.0/uTexSize.x), 0.0 );
static vec2 ver = vec2 ( 0.0 , (1.0/uTexSize.y));
vec2 uv1,uv10,uv2,uv3,uv6,dz,dz0,dz1;
vec3 noise, ret1, ret2, neu, mus;
float matan (float x)
{return x*(1.061 - abs(x)*0.274);}
float matan2 (float im, float re)
{float x;
if (abs(re) > abs(im))
{x = matan (im/re);
if (re<0) {x += M_PI;}
}
else
{x = M_PI / 2.0 -matan (re/im);
if (im<0) {x += M_PI;}
}
return (x>=M_PI? x - 2.0*M_PI: x);
}
//mus = max(mus,stars);
uv2 = vec2 (2.0 * length (uv10), ang2).yx;
uv2 = uv2*.2+vec2(0.07*uTime,.5);
uv2=fract(uv2);
vec3 bk = GetBlur2(uv2) * 2.0*(1.0 - rad) + .2;
ret = sqrt(ret1)*(1.0 + ret2)*(.25+mus) ;
ret *= 1+6*length(dz);
ret += clamp01(stars)*.7;
ret += bk* clamp01(1.0 - lum(ret1) * 16.0)*sqrt(audioMidSmooth + 1.0)*clamp01(0.035/(0.001+sqrt(length(uv10))));
ret *= 1.3-rad;
//ret = GetPixel(uv);
}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv10 = (uv-.5)*uAspect.xy;
float ang1 = matan2 (uv10.x,uv10.y)/M_PI;
float ang2 = 0.5 + (1.0 - abs( fract(ang1 * 0.5) * 2.0 - 1.0 )-.5);
float z = q5;
uv1 = vec2 (.6+3*z-z/length (uv10), ang2).yx;
ret1= ret2= 0;
dz= dz1=0;
uv3 = uv1;
float mask = clamp01(4.0 * uv3.y) * clamp01(rad * 2.0);
uv3 = fract(uv3);
dz0.x = (lum(GP(uv3+hor))- lum(GP(uv3-hor)));
dz0.y = (lum(GP(uv3+ver))- lum(GP(uv3-ver)));
dz0.x += 2.0 * (lum(GB(uv3+hor))- lum(GB(uv3-hor)));
dz0.y += 2.0 * (lum(GB(uv3+ver))- lum(GB(uv3-ver)));
dz +=  mask*dz0 / 2.0;
ret1 = max(ret1,(GP(uv3)+GB(uv3)) / 2.0*mask);
ret2 = abs(GetPixel(uv3)-GetBlur1(uv3).xy);
mus = 1.0 / length(sin(12.0 * (uv1+dz / 2.0 + 0.25*(ret1-0.5)) +uTime))*rad*(1.0 - rad);
float stars = 0;
int anz = 6;
uv2 = vec2 (0.02/length (uv10), ang2).yx;
for (int n=1; n <= anz; n++)
{
vec2 uv4 = 8.0*((1.0+n)*(uv2+(dz+(ret1-.5)) + 0.1*n )+ vec2( 0.0 ,uTime*.1));
float smask = clamp01(texture(sampler_pw_noise_lq,uv4 / 256.0)-.95);
stars = max(stars,(0.1/pow(length(fract(uv4)-.5), 2.0 )*smask));
n++;
  fragColor = vec4(ret, 1.0);
}

